def is_samepatterns(patterns, sequence):
    """
    Checks if the given sequence follows the pattern in the patterns array.
    The pattern is considered a match if it contains the same unique elements as the sequence.

    Args:
        patterns (list): A list of patterns.
        sequence (list): A list of elements to check against the patterns.

    Returns:
        bool: True if the sequence follows the pattern, False otherwise.
    """
    if len(set(patterns)) != len(set(sequence)):
        return False

    pattern_dict = {}
    for i, pattern in enumerate(patterns):
        if pattern in pattern_dict:
            pattern_dict[pattern].append(i)
        else:
            pattern_dict[pattern] = [i]

    sequence_dict = {}
    for i, elem in enumerate(sequence):
        if elem in sequence_dict:
            sequence_dict[elem].append(i)
        else:
            sequence_dict[elem] = [i]

    for key in sequence_dict:
        if key not in pattern_dict or set(sequence_dict[key]) != set(pattern_dict[key]):
            return False

    return True

