def extract_missing(ranges, start, end):
    missing = []
    for i in range(start, end + 1):
        found = False
        for r in ranges:
            if r[0] <= i <= r[1]:
                found = True
                break
        if not found:
            missing.append((i, end))
    for r in ranges:
        for i in range(r[1] + 1, r[0]):
            found = False
            for rr in ranges:
                if rr[0] <= i <= rr[1]:
                    found = True
                    break
            if not found:
                missing.append((r[1] + 1, i))
    return missing
